import subprocess

from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases.exceptions import TestFailedOnTeardownError
from taf.rfrl.csv4all.resources.test_cases.upgrade_test import UpgradeTest
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion, FallbackFaultNotAppear
from taf.rfrl.csv4all.resources.node.feature.utilities.nescrotta.nescrotta import Nescrotta
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, function_wrapper
from taf.rfrl.csv4all.resources.node.feature.fdsw.fdsw_node_factory import FdswNodeFactory
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, run_process, wait_until_success


class FdswTest(UpgradeTest):
    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = False,
                 feature: Optional[str] = None,
                 fallback: Optional[bool] = False, rollback: Optional[bool] = False, log_level: Optional[str] = 'INFO',
                 stop_test_after_fail: bool = False, config_type: str = None, artifactory_location: str = "espoo2",
                 package_suffix: str = "A54", yaft_path: str = "/home/ute", virtualenv_dir: str = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, use_external_storage, download_path, use_testpackage, stop_test_after_fail,
                         artifactory_location, package_suffix, None, False, yaft_path, virtualenv_dir,
                         detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.node_factory = FdswNodeFactory()
        self.feature = feature
        self.config_type = config_type
        self.nescrotta = None
        self.burak_path = "/mnt/burak/"
        self.burak_mounted = False
        self.restore_to_target_sw = restore_to_target_sw
        self.report_to_rp = report
        self.perform_fallback = fallback
        self.perform_rollback = rollback
        self.fdsw_log_level = log_level
        self.virtualenv_dir = virtualenv_dir

    def test_operation(self, node):
        failed_nodes = self.fdsw_test_operation(node)
        if self.report_to_rp:
            self.test_reporter.get_end_time()
            self.test_reporter.report_result_to_uuf_dashboard(node,
                                                              "failed" if failed_nodes else "passed", "",
                                                              self.current_iteration)
        return failed_nodes

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None):
        pass

    @method_decorator()
    def fdsw_test_operation(self, node):
        try:
            self.setup_burak_if_needed()
            if self.report_to_rp:
                self.test_reporter.get_start_time()
            self.multi_runner.start_log_tracing_all_nodes()
            self.prepare_yaft(node)
            self.copy_yaft_if_remote(node)
            node.prepare_node_before_yaft(self.yaft_path, self.virtualenv_dir)
            test_logger("Performing yaft on both partitions")
            for _ in range(2):
                node.perform_yaft_to_fdsw(self.yaft_path, self.virtualenv_dir)
            node.setup_fdsw(log_level=self.fdsw_log_level)
            node.turn_off_netboot_on_fdsw()
            node.restore_target_sw()
            if not self.passed_logs_gathered:
                self.gather_mumin_logs_and_snapshot("update")
                self.send_snapshot_to_nescrotta(f"{self.current_logs_dir}/update/{node.node_alias}", "Upgrade")
            test_logger(f"[{node.node_alias}] UPGRADE PASSED", hyperlink=True)
            return {}
        except Exception as e:
            test_logger(e, "error")
            test_logger(f"[{node.node_alias}] UPGRADE FAILED", 'error')
            try:
                self.gather_mumin_logs_and_snapshot("update")
            except Exception as e:
                test_logger(e, console=False)
            return {node.node_alias}
        finally:
            self.stop_test_log_tracing(logs_dir=self.current_logs_dir)

    def run_test_precondition(self):
        self.setup_admin_connections()
        self.check_free_space()

    def test(self):
        for node in self.test_nodes:
            self.failed_nodes[node.node_alias] = self.test_operation(node)
            if self.perform_rollback:
                self.sw_rollback_operation(node)
            if self.perform_fallback:
                try:
                    self.multi_runner.start_log_tracing_all_nodes()
                    if self.perform_rollback:
                        test_logger("Preparing node for fallback")
                        node.perform_activation_sbts_from_fdsw(self.fdsw_log_level)
                    try:
                        node.verify_node_bts_state()
                    except Exception as e:
                        test_logger(e, console=False)
                    if self.check_nodes_state_before_operation(node, node.target_sw):
                        self.sw_fallback_operation(node)
                    else:
                        raise WrongSwVersion
                except Exception as e:
                    test_logger(e, "ERROR")
                    self.gather_logs(node)
                    self.failed_nodes[node.node_alias] = {node.node_alias}
                finally:
                    self.multi_runner.stop_log_tracing_and_download_from_all_nodes(f"{self.current_logs_dir}/fallback")
        self.turn_on_netboot(node)
        self.verify_failed_nodes_after_iteration()

    @method_decorator()
    def sw_rollback_operation(self, node):
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            if self.check_nodes_state_before_operation(node, node.target_sw):
                node.perform_rollback()
                node.setup_fdsw(log_level=self.fdsw_log_level)
            if not self.passed_logs_gathered:
                self.gather_technical_logs(node, "rollback")
        finally:
            self.multi_runner.stop_log_tracing_and_download_from_all_nodes(f"{self.current_logs_dir}/rollback")

    @method_decorator()
    def sw_fallback_operation(self, node):
        node.prepare_node_before_fallback()
        node.execute_reset_loop()
        node.setup_fdsw(log_level=self.fdsw_log_level)
        node.verify_fallback_fault()
        if not self.passed_logs_gathered:
            self.gather_technical_logs(node, "fallback")
        node.clear_fallback_fault()

    @method_decorator()
    def check_nodes_state_before_operation(self, node, sw: str) -> bool:
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.run_recovery_method(failed_nodes)
        try:
            node.verify_active_sw_version(sw)
            return True
        except WrongSwVersion:
            return False

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            self.umount_nescrotta()
            if self.burak_mounted:
                self.umount_burak()
            if self.restore_to_target_sw:
                for node in self.test_nodes:
                    try:
                        if node.check_active_sw_version_via_ssh(node.source_sw):
                            node.perform_activation_sbts_from_fdsw(self.fdsw_log_level)
                            node.verify_node_bts_state()
                    except Exception:
                        raise TestFailedOnTeardownError
        except Exception as e:
            test_logger(e, "error")
        finally:
            for node in self.test_nodes:
                node.teardown_fdsw_connection()
            super().test_teardown()

    def test_setup(self):
        super().test_setup()
        self.download_builds_from_wft({node.source_sw for node in self.test_nodes})
        self.setup_nescrotta()
        self.nescrotta.mount_nescrotta()
        if self.burak_mounted:
            for node in self.test_nodes:
                node.download_path = self.burak_path

    def mount_burak(self):
        if not subprocess.getoutput(f"sudo df -ah | grep {self.burak_path.rstrip('/')}"):
            cmd = f"sudo mkdir {self.burak_path};sudo chmod 777 {self.burak_path};" \
                  f"sudo mount -t cifs //burak2.intra.noklab.net/csv4all/UUF/SBTS " \
                  f"{self.burak_path} " \
                  f"-o username=uufwro,password=uufpass18,rw,nounix,file_mode=0777,dir_mode=0777," \
                  f"uid=ute,gid=ute,domain=noklab,vers=3.0"
            process = subprocess.Popen(cmd, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT)
            output, error = process.communicate()
            if process.returncode != 0:
                test_logger(f"Output: {output}", "DEBUG")
                test_logger(f"Error: {error}", "DEBUG")
                raise subprocess.CalledProcessError(returncode=process.returncode, cmd=process.args, stderr=error)

    def umount_burak(self):
        if subprocess.getoutput(f"df -ah | grep {self.burak_path.rstrip('/')}"):
            subprocess.Popen(f"sudo umount {self.burak_path}", shell=True)

    @function_wrapper
    def send_snapshot_to_nescrotta(self, snapshot_directory, operation):
        test_logger("Checking if sending snapshot to Nescrotta is possible")
        self.nescrotta.send_snapshot_to_nescrotta(snapshot_directory, operation)

    def setup_nescrotta(self):
        target_release = self.wft.get_sw_release(self.test_nodes[0].target_sw).replace('SBTS', '')
        source_release = self.test_nodes[0].source_sw.split("_")[2]
        self.nescrotta = Nescrotta(target_release, source_release, self.feature, self.config_type)

    def umount_nescrotta(self):
        if self.nescrotta:
            self.nescrotta.umount_nescrotta()

    def prepare_yaft(self, node):
        self.wft.target_sw_dict.get(f"{node.target_sw}_release_BTSSM_downloadable_{self.package_suffix}")
        target_sw_path = self.wft.target_sw_dict.get(f"{node.source_sw}_release_BTSSM_downloadable")
        commands = [f"cp -R {target_sw_path} {self.yaft_path}",
                    f"cp {node.backup_swconfig_path_primary_smod} "
                    f"{self.yaft_path}/libyaft/swconfig.txt"]
        for command in commands:
            test_logger(f"Executing command: {command}", console=False)
            output = wait_until_success(120, 2, run_process, command)
            test_logger(output, console=False)

    @method_decorator()
    def gather_technical_logs(self, node, operation):
        try:
            snapshot_directory = f"{self.current_logs_dir}/{operation}/"
            node.get_technical_logs(snapshot_directory, filename=f"Snapshot_{node.mrbts_id}_{node.source_sw}_"
                                                                 f"{self.get_timestamp()}")
            self.send_snapshot_to_nescrotta(snapshot_directory, operation.capitalize())
        except Exception as e:
            test_logger(e, "ERROR")
            test_logger(f"Gather Technical Logs failed", "ERROR")

    def setup_burak_if_needed(self):
        if not self.use_ext_storage:
            for node in self.test_nodes:
                if node.smod_type == 'FSMF' and "FDSW19" in node.source_sw:
                    node.download_path = self.burak_path
                    self.mount_burak()
                    self.burak_mounted = True

    @method_decorator()
    def copy_yaft_if_remote(self, node):
        if not node.local_host:
            command = f"rsync -au {self.yaft_path} {node.vm.get('user')}@{node.vm.get('host')}:" \
                      f"{self.yaft_path.rsplit('/', 1)[0]}"
            test_logger(f"Executing command: {command}", "DEBUG")
            run_process(command)

    def hwf_migration_precheck(self):
        pass

    @method_decorator()
    def gather_logs(self, node):
        try:
            self.gather_mumin_logs_and_snapshot()
        except:
            self.gather_technical_logs(node, "fallback")

    def turn_on_netboot(self, node):
        if node.master_netboot_changed:
            node.change_netboot_state("on")
        if node.slave_netboot_changed:
            node.change_netboot_state("on", slave_smod=True)
